using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "DiceSecondActionLogic_AllTargets", menuName = "Data/Battle/Logics/Dice Action/Dice Second Action Logic/DiceSecondActionLogic_AllTargets")]
public class DiceSecondActionLogic_AllTargets : DiceSecondActionLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	public override void OnDrop(ActionFace actionFace, GameObject target, GameObject source)
	{
		actionFace.SecondBattleAction.AreaCastTargetAmount(currentActiveUnits.GetCurrentActiveUnits(), actionFace.SecondModifiedActionValue, source);
	}
}
